#!/usr/bin/env python3
"""s02_structure.py -- map the key structure (with line numbers) of the
committed copies of the four object files and the frozen v2 copy, so that
sections can be read by line range.  Own code; PyYAML (compose API) only.
Usage: s02_structure.py <file> [max_depth]
"""
import sys, yaml

path = sys.argv[1]
maxd = int(sys.argv[2]) if len(sys.argv) > 2 else 3
with open(path, "rb") as f:
    text = f.read().decode("utf-8")
node = yaml.compose(text)

def walk(n, depth, prefix):
    if depth > maxd:
        return
    if isinstance(n, yaml.MappingNode):
        for k, v in n.value:
            key = k.value
            print(f"{'  '*depth}{key}  [L{k.start_mark.line+1}-L{v.end_mark.line+1}]")
            walk(v, depth + 1, prefix + "." + key)
    elif isinstance(n, yaml.SequenceNode):
        for i, v in enumerate(n.value):
            label = ""
            if isinstance(v, yaml.MappingNode):
                for kk, vv in v.value:
                    if kk.value in ("id", "joint", "item", "name"):
                        label = f" {kk.value}={vv.value if isinstance(vv, yaml.ScalarNode) else '...'}"
                        break
            print(f"{'  '*depth}[{i}]{label[:80]}  [L{v.start_mark.line+1}-L{v.end_mark.line+1}]")
            walk(v, depth + 1, prefix + f"[{i}]")

walk(node, 0, "")

#!/usr/bin/env python3
"""s10_j3_kreadings_fixture.py -- TASK-20261002-3cd1f8, joint J3 items (i) to (iii).

OWN CODE. The frozen instrument (experiments/EXP-SEMBIN-81dc96/code/joint_balance.py)
is NOT imported or executed: its stage-1 path is RE-IMPLEMENTED here from its text
(k_of, log2_factorial via lgamma, log2_yield with its -40 / +10 guards and expm1,
log2_solve_cost block_n4w = 4 omega log2 n, stage1 = k + solve - log2_p, first minimum
over m = 2..min(30, n) ascending with strict less-than). A second, disjoint evaluation
uses mpmath at 60 digits with exact rationals for k.

(i)  stage 1 under MI-1 (k = n/m) and the ceiled reading (k = ceil(n/m)) at every
     claim-(A) degree, minimised over m in 2..30: value, argmin, runner-up, gap, move.
(ii) fixture F1 exactly as frozen at 571 and 283; distance to target and slack;
     admissible evaluation differences (summation order, log2 m! route, expm1 vs
     1 - exp, math.fsum, numpy float64 and float32 paths); false-PASS readings:
     ceiled, cofactor-absorbed (charge_cofactor False), omega 2.376 (plus 2.807, 2.0).
(iii) A(571, m) under both readings (O-J4-1 bias, sign at every m); a value-free check
     that every MI-1 threshold entry is no later than its ceiled entry (D*_R per the
     contract's definitions over D in 2..64, both curves, both readings) -- ONLY the
     comparison outcome is printed, never a D* value; G4 margins under MI-1 and under
     the ceiled reading at omega 3 (O-J5-2 slack), with the omega at which each ceiled
     margin turns non-positive.
Libraries: math, fractions, mpmath 1.3.0, numpy 2.4.6.
"""
import json, math, os
from fractions import Fraction
import mpmath as mp
import numpy as np
mp.mp.dps = 60
SCR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLAIM_A = (79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571)

# ------------------------------------------------------------ mpmath reference
def k_exact(n, m, reading):
    return Fraction(n, m) if reading == "MI-1" else Fraction(-(-n // m))
def A_mp(n, m, reading):
    k = k_exact(n, m, reading)
    e = m * k - n
    x = mp.power(2, mp.mpf(e.numerator) / e.denominator) / mp.factorial(m)
    return mp.mpf(k.numerator) / k.denominator - mp.log(-mp.expm1(-x), 2)
def S_B(n, D, omega):
    return D * mp.mpf(omega) * mp.log(n, 2)
def W_mp(n, D):
    return mp.log(sum(math.comb(n, d) for d in range(D + 1)), 2)
def S_M(n, D, omega):
    return mp.mpf(omega) * (W_mp(n, D) - W_mp(n, 4) + 4 * mp.log(n, 2))
def stage1_mp(n, m, reading, omega="3", charge=True):
    return A_mp(n, m, reading) + (S_B(n, 4, mp.mpf(omega)) if charge else 0)
def first_min(vals):
    best = None
    for (m, v) in vals:
        if best is None or v < best[1]:
            best = (m, v)
    return best
def ordered(vals):
    return sorted(vals, key=lambda mv: (mv[1], mv[0]))

kr = []
for n in CLAIM_A:
    row = {"n": n}
    best = {}
    for reading in ("MI-1", "ceiled"):
        vals = [(m, stage1_mp(n, m, reading)) for m in range(2, min(30, n) + 1)]
        m1, v1 = first_min(vals)
        o = ordered(vals)
        (mr, vr) = o[1] if o[0][0] == m1 else o[0]
        best[reading] = v1
        row[reading] = {"C_I": mp.nstr(v1, 12), "m_star": m1, "runner_up_m": mr,
                        "runner_up_gap": mp.nstr(vr - v1, 8), "relation_store_k_at_m_star": mp.nstr(mp.mpf(k_exact(n, m1, reading).numerator) / k_exact(n, m1, reading).denominator, 8)}
    mv = best["ceiled"] - best["MI-1"]
    row["move_ceiled_minus_MI1"] = mp.nstr(mv, 10)
    row["direction"] = "ceiled lower" if mv < 0 else "ceiled not lower"
    kr.append(row)

a571 = []
for m in range(2, 31):
    a1, a2 = A_mp(571, m, "MI-1"), A_mp(571, m, "ceiled")
    a571.append({"m": m, "A_MI1": mp.nstr(a1, 10), "A_ceiled": mp.nstr(a2, 10), "diff": mp.nstr(a2 - a1, 8),
                 "sign": "neg" if a2 < a1 else ("zero" if a2 == a1 else "pos")})
diffs = [mp.mpf(r["diff"]) for r in a571]
a571_summary = {"m_count": len(a571), "neg": sum(r["sign"] == "neg" for r in a571),
                "zero": sum(r["sign"] == "zero" for r in a571), "pos": sum(r["sign"] == "pos" for r in a571),
                "largest_drop": mp.nstr(min(diffs), 8), "smallest_drop": mp.nstr(max(diffs), 8),
                "drop_at_m12": [r["diff"] for r in a571 if r["m"] == 12][0]}

# ------------------------------------------------------------ instrument re-implementation (double)
def jb_log2_factorial(t): return math.lgamma(t + 1.0) / math.log(2.0)
def jb_k_of(n, m, reading): return n / m if reading == "unceiled" else float(-(-n // m))
def jb_log2_yield(n, t, k, fact=jb_log2_factorial, naive=False):
    log2_x = t * k - n - fact(t)
    if log2_x < -40.0:
        return log2_x
    if log2_x > 10.0:
        return 0.0
    x = 2.0 ** log2_x
    return math.log2(1.0 - math.exp(-x)) if naive else math.log2(-math.expm1(-x))
def jb_stage1(n, m, t, k_reading="unceiled", omega=3.0, charge=True, order=0, fact=jb_log2_factorial, naive=False):
    k = jb_k_of(n, m, k_reading)
    solve = 4.0 * omega * math.log2(n) if charge else 0.0
    lp = jb_log2_yield(n, t, k, fact, naive)
    if order == 0: return k + solve - lp            # the instrument's order
    if order == 1: return k + (solve - lp)
    if order == 2: return (k - lp) + solve
    if order == 3: return math.fsum([k, solve, -lp])
def C_I(n, **kw):
    best = None
    for m in range(2, min(30, n) + 1):
        v = jb_stage1(n, m, m, **kw)
        if best is None or v < best[0]:
            best = (v, m)
    return best
TARGET = {571: (186.307, 12), 283: (147.649, 9)}
TOL = 5.0e-4
def passes(n, val, m):
    return abs(val - TARGET[n][0]) <= TOL and m == TARGET[n][1]
fixture = {}
variants = {
    "as_frozen": {},
    "ceiled_reading": {"k_reading": "ceiled"},
    "cofactor_absorbed": {"charge": False},
    "omega_2.376": {"omega": 2.376},
    "omega_2.807": {"omega": 2.807},
    "omega_2.0": {"omega": 2.0},
}
for name, kw in variants.items():
    out = {}
    ok_all = True
    for n in (571, 283):
        v, m = C_I(n, **kw)
        p = passes(n, v, m)
        ok_all &= p
        out[str(n)] = {"value": repr(v), "argmin": m, "abs_distance_to_target": repr(abs(v - TARGET[n][0])), "passes": p}
    out["pass_rule_overall"] = "PASS" if ok_all else "FAIL"
    fixture[name] = out

# exact distances and slack
exact = {}
for n in (571, 283):
    vals = [(m, stage1_mp(n, m, "MI-1")) for m in range(2, 31)]
    m1, v1 = first_min(vals)
    dist = abs(v1 - mp.mpf(str(TARGET[n][0])))
    exact[str(n)] = {"C_I_exact_60_digits": mp.nstr(v1, 20), "argmin": m1,
                     "abs_distance_to_target": mp.nstr(dist, 8), "slack_to_band": mp.nstr(mp.mpf("5.0e-4") - dist, 8),
                     "rounded_3dp": mp.nstr(v1, 3 + len(str(int(v1)))), "rounded_4dp": mp.nstr(v1, 4 + len(str(int(v1))))}

# admissible evaluation differences at the argmin cell (double precision paths)
probes = {}
for n in (571, 283):
    m = TARGET[n][1]
    ref = stage1_mp(n, m, "MI-1")
    paths = {
        "instrument_order": jb_stage1(n, m, m),
        "order_k_plus_(solve-lp)": jb_stage1(n, m, m, order=1),
        "order_(k-lp)+solve": jb_stage1(n, m, m, order=2),
        "math.fsum": jb_stage1(n, m, m, order=3),
        "log2_factorial_exact_int": jb_stage1(n, m, m, fact=lambda t: math.log2(math.factorial(t))),
        "naive_1-exp": jb_stage1(n, m, m, naive=True),
    }
    # numpy float64 and float32 end-to-end
    for dt in (np.float64, np.float32):
        k = dt(n) / dt(m)
        log2_x = k * dt(m) - dt(n) - dt(math.lgamma(m + 1.0) / math.log(2.0))
        x = dt(2.0) ** log2_x
        lp = np.log2(-np.expm1(-x))
        solve = dt(4.0) * dt(3.0) * np.log2(dt(n))
        paths["numpy_" + dt.__name__] = float(k + solve - lp)
    probes[str(n)] = {name: {"value": repr(v), "deviation_from_exact": mp.nstr(mp.mpf(v) - ref, 4),
                             "abs_distance_to_target": repr(abs(v - TARGET[n][0])),
                             "within_band": abs(v - TARGET[n][0]) <= TOL}
                      for name, v in paths.items()}
# the printed 4-decimal figure 147.6495 against the 3-decimal target, in double
printed_edge = {"147.6495_minus_147.649_double": repr(147.6495 - 147.649),
                "le_5.0e-4": (abs(147.6495 - 147.649) <= 5.0e-4),
                "exact_decimal": "5.0e-4 exactly in decimal"}

# ------------------------------------------------------------ O-J4-1: MI-1 table no later than ceiled (value-free)
rho = {r["curve"]: mp.mpf(r["rho"]) for r in json.load(open(os.path.join(SCR, "out", "s05_rho.json")))["rows"]}
def dstar(c, m, reading, R):
    a = A_mp(571, m, reading)
    for D in range(2, 65):
        S = S_B(571, D, 3) if R == "R-B" else S_M(571, D, 3)
        if a + S - rho[c] > 0:
            return D
    return 65   # token "no crossing at D <= 64", ordered above every grid value
cmp_count = {"entries": 0, "MI1_no_later": 0, "MI1_strictly_earlier": 0, "MI1_later": 0}
for c in ("K-571", "B-571"):
    for R in ("R-B", "R-M"):
        for m in range(2, 31):
            d1, d2 = dstar(c, m, "MI-1", R), dstar(c, m, "ceiled", R)
            cmp_count["entries"] += 1
            cmp_count["MI1_no_later"] += (d1 <= d2)
            cmp_count["MI1_strictly_earlier"] += (d1 < d2)
            cmp_count["MI1_later"] += (d1 > d2)

# ------------------------------------------------------------ O-J5-2: G4 slack under MI-1 and ceiled (omega 3)
g4 = []
for c, n in (("K-283", 283), ("B-283", 283), ("K-163", 163), ("B-163", 163), ("K-233", 233), ("B-233", 233),
             ("ECC2-238", 239), ("ECC2K-238", 239)):
    rec = {"curve": c, "n": n}
    for reading in ("MI-1", "ceiled"):
        vals = [(m, A_mp(n, m, reading)) for m in range(2, 31)]
        m1, a1 = first_min(vals)
        marg = a1 + S_B(n, 4, 3) - rho[c]
        # omega at which this margin reaches zero (argmin is omega-independent under block_n4w)
        w0 = (rho[c] - a1) / (4 * mp.log(n, 2))
        rec[reading] = {"m_star": m1, "margin_omega3": mp.nstr(marg, 8), "omega_at_zero_margin": mp.nstr(w0, 6)}
    g4.append(rec)

print(json.dumps({"kreading_table": kr, "A_571": a571, "A_571_summary": a571_summary,
                  "fixture_double_reimplementation": fixture, "fixture_exact": exact,
                  "evaluation_difference_probes": probes, "printed_edge_check": printed_edge,
                  "bias_check_value_free": cmp_count, "g4_margins": g4,
                  "versions": {"python": __import__("sys").version.split()[0], "mpmath": mp.__version__, "numpy": np.__version__}},
                 indent=1))

#!/usr/bin/env python3
"""s12_divisor_cells.py -- TASK-20261002-3cd1f8, J3 wording check: at which claim-(A)
cells (n, m), m in 2..30, do the MI-1 and ceiled stage-1 values coincide (m divides n)?
Exact rational k; mpmath 60 digits. Own code."""
import mpmath as mp
from fractions import Fraction
mp.mp.dps = 60
def A(n, m, ceiled):
    k = Fraction(-(-n // m)) if ceiled else Fraction(n, m)
    e = m * k - n
    x = mp.power(2, mp.mpf(e.numerator) / e.denominator) / mp.factorial(m)
    return mp.mpf(k.numerator) / k.denominator - mp.log(-mp.expm1(-x), 2)
CLAIM_A = (79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571)
eq, lower, higher = [], 0, []
for n in CLAIM_A:
    for m in range(2, min(30, n) + 1):
        d = A(n, m, True) - A(n, m, False)
        if d == 0: eq.append((n, m))
        elif d < 0: lower += 1
        else: higher.append((n, m, mp.nstr(d, 6)))
print({"cells": sum(min(30, n) - 1 for n in CLAIM_A), "ceiled_lower": lower, "equal_cells": eq, "ceiled_higher_cells": higher})

